"""Builds app/assets/supabase_setup.sql: every migration in order, for setting up a new server in one paste.

Run after adding or changing a migration:  python supabase/build_setup.py
"""
from pathlib import Path

root = Path(__file__).resolve().parent
migrations = sorted((root / 'migrations').glob('*.sql'))
header = (
    '-- Bone Data Manager — complete server setup.\n'
    '-- Paste everything into Supabase → SQL Editor → Run, once, on a NEW project.\n'
    '-- Generated by supabase/build_setup.py from supabase/migrations; do not edit by hand.\n\n'
)
body = '\n'.join(m.read_text(encoding='utf-8') for m in migrations)
out = root.parent / 'app' / 'assets' / 'supabase_setup.sql'
out.parent.mkdir(exist_ok=True)
out.write_text(header + body, encoding='utf-8', newline='\n')
print(f'wrote {out} from {len(migrations)} migrations')
